class Solution:
    def generate(self, numRows: int) -> List[List[int]]:
        if numRows == 1:
            return 1
        elif numRows == 2:
            return [[1], [1, 1]]
        else:
            cur_list = [[1], [1, 1]]
            for i in range(2, numRows):
                cur_list.append([1] * (i + 1))
                # eg. i = 3时, j从1到2
                for j in range(1, i):
                    cur_list[i][j] = cur_list[i - 1][j - 1] + cur_list[i - 1][j]
            return cur_list
